fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let width_usize = width as usize;

    // If the original is already wide enough, return it unchanged.
    if orig_len >= width_usize {
        orig
    } else {
        // Otherwise, build a new Vec with the needed capacity,
        // fill the leading positions, then append the original.
        let mut res = Vec::with_capacity(width_usize);
        let pad_len = width_usize - orig_len;

        for _ in 0..pad_len {
            res.push(fillchar);
        }
        res.extend(orig);

        res
    }
}

